use std::collections::BTreeMap;
use std::fmt;
use std::fs::File;
use std::io::{self, BufRead, BufReader, ErrorKind};

#[derive(Debug)]
enum ConfigError {
    Io(io::Error),
    Syntax { line: usize, text: String },
    Duplicate { line: usize, key: String },
}

impl fmt::Display for ConfigError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            ConfigError::Io(e) => write!(f, "read error: {e}"),
            ConfigError::Syntax { line, text } => write!(f, "line {line}: expected key = value, got {text}"),
            ConfigError::Duplicate { line, key } => write!(f, "line {line}: {key} is set twice"),
        }
    }
}

impl From<io::Error> for ConfigError {
    fn from(e: io::Error) -> Self {
        ConfigError::Io(e)
    }
}

fn parse_config<R: BufRead>(reader: R) -> Result<BTreeMap<String, String>, ConfigError> {
    let mut map = BTreeMap::new();
    for (i, line) in reader.lines().enumerate() {
        let line = line?;
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }
        let Some((key, value)) = trimmed.split_once('=') else {
            return Err(ConfigError::Syntax { line: i + 1, text: trimmed.to_string() });
        };
        let key = key.trim();
        if key.is_empty() {
            return Err(ConfigError::Syntax { line: i + 1, text: trimmed.to_string() });
        }
        if map.insert(key.to_string(), value.trim().to_string()).is_some() {
            return Err(ConfigError::Duplicate { line: i + 1, key: key.to_string() });
        }
    }
    Ok(map)
}

fn load_or_default(path: &str) -> Result<BTreeMap<String, String>, ConfigError> {
    match File::open(path) {
        Ok(file) => parse_config(BufReader::new(file)),
        Err(e) if e.kind() == ErrorKind::NotFound => Ok(BTreeMap::new()),
        Err(e) => Err(e.into()),
    }
}

unitTests:
use std::io::Cursor;

test("parses from any reader", || {
    let text = "# window\nwidth = 800\n\n  title =  My Game  \nempty =\n";
    let map = parse_config(Cursor::new(text)).unwrap();
    check_eq(map["width"].as_str(), "800");
    check_eq(map["title"].as_str(), "My Game");
    check_eq(map["empty"].as_str(), "");
    check_eq(map.len(), 3);
});

test("errors with line numbers", || {
    let e = parse_config(Cursor::new("a = 1\nnonsense\n")).unwrap_err();
    check_eq(e.to_string(), "line 2: expected key = value, got nonsense");
    let e = parse_config(Cursor::new("a = 1\n# c\na = 2\n")).unwrap_err();
    check_eq(e.to_string(), "line 3: a is set twice");
    check(matches!(parse_config(Cursor::new(" = 5")), Err(ConfigError::Syntax { line: 1, .. })));
});

test("missing file means defaults", || {
    let map = load_or_default("this/file/does/not/exist.cfg").unwrap();
    check(map.is_empty());
    let io_error: ConfigError = std::io::Error::new(std::io::ErrorKind::Other, "disk on fire").into();
    check_eq(io_error.to_string(), "read error: disk on fire");
});

